#!/usr/bin/env node
// Condense a captured conversation JSONL into a readable digest.
// Usage: node condense.mjs <file.jsonl> [--tools] [--max <chars per text>]
import { readFileSync } from 'node:fs';

const [file] = process.argv.slice(2).filter((a) => !a.startsWith('--'));
const showTools = process.argv.includes('--tools');
const maxIdx = process.argv.indexOf('--max');
const MAX = maxIdx > -1 ? Number(process.argv[maxIdx + 1]) : 1200;

const clip = (s) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > MAX ? `${t.slice(0, MAX)} …[+${t.length - MAX}]` : t;
};

for (const line of readFileSync(file, 'utf8').split('\n')) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = (e.timestamp || '').replace(/\.\d+Z$/, 'Z');
  const msg = e.message || {};
  const role = e.type || msg.role;
  const content = Array.isArray(msg.content) ? msg.content : msg.content ? [{ type: 'text', text: msg.content }] : [];
  for (const c of content) {
    if (c.type === 'text' && c.text?.trim()) {
      console.log(`\n[${ts}] ${role.toUpperCase()}: ${clip(c.text)}`);
    } else if (c.type === 'thinking' && c.thinking?.trim()) {
      console.log(`[${ts}] (thinking) ${clip(c.thinking)}`);
    } else if (c.type === 'tool_use') {
      const inp = JSON.stringify(c.input);
      console.log(`[${ts}] TOOL ${c.name}: ${clip(inp).slice(0, showTools ? MAX : 220)}`);
    } else if (c.type === 'tool_result' && showTools) {
      const body = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      console.log(`[${ts}]   -> ${clip(body).slice(0, 400)}`);
    }
  }
}

