#!/usr/bin/env node
// Print the human's own turns from a captured conversation JSONL.
// Filters out tool results, system reminders, hook output and harness pseudo-turns.
import { readFileSync } from 'node:fs';

const files = process.argv.slice(2).filter((a) => !a.startsWith('--'));
const MAX = 2000;

const clip = (s) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > MAX ? `${t.slice(0, MAX)} …[+${t.length - MAX}]` : t;
};

for (const file of files) {
  console.log(`\n######## ${file.split('/').pop()}`);
  for (const line of readFileSync(file, 'utf8').split('\n')) {
    if (!line.trim()) continue;
    let e;
    try { e = JSON.parse(line); } catch { continue; }
    const msg = e.message || {};
    if ((e.type || msg.role) !== 'user') continue;
    if (e.isMeta) continue;
    const content = Array.isArray(msg.content) ? msg.content : msg.content ? [{ type: 'text', text: msg.content }] : [];
    for (const c of content) {
      if (c.type !== 'text') continue;
      let t = String(c.text || '');
      t = t.replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '').trim();
      if (!t) continue;
      if (t.startsWith('<')) continue; // harness pseudo-turn
      if (/^(Caveat:|\[Request interrupted)/.test(t)) continue;
      console.log(`\n[${(e.timestamp || '').replace(/\.\d+Z$/, 'Z')}] USER: ${clip(t)}`);
    }
  }
}

